BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path TO public, extensions;
SELECT no_plan();
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='private.audit_verification_requests'::regclass),'request mapping has RLS');
SELECT ok(NOT has_table_privilege('authenticated','private.audit_verification_requests','SELECT'),'authenticated cannot read request mapping');
SELECT ok(NOT has_function_privilege('anon','public.begin_audit_verification_request(uuid,text)','EXECUTE'),'anon cannot begin verification request');
SELECT ok(NOT has_function_privilege('authenticated','public.begin_audit_verification_request(uuid,text)','EXECUTE'),'authenticated cannot begin verification request');
SELECT ok(has_function_privilege('service_role','public.begin_audit_verification_request(uuid,text)','EXECUTE'),'service role can begin verification request');
SELECT throws_ok($$ SELECT public.begin_audit_verification_request(NULL,repeat('a',64)) $$,'P0001','audit_verification_request_invalid','null request rejected');
SELECT throws_ok($$ SELECT public.begin_audit_verification_request('15200000-0000-4000-8000-000000000301','invalid') $$,'P0001','audit_verification_request_invalid','invalid context rejected');
SET LOCAL ROLE service_role;
SELECT set_config('test.request.run',public.begin_audit_verification_request('15200000-0000-4000-8000-000000000301',repeat('a',64)),true);
RESET ROLE;
INSERT INTO public.audit_events(id,action_type,resource_type) VALUES ('15200000-0000-4000-8000-000000000303','synthetic.request-later','test');
SET LOCAL ROLE service_role;
SELECT is(public.begin_audit_verification_request('15200000-0000-4000-8000-000000000301',repeat('a',64)),current_setting('test.request.run'),'retry returns the same snapshot');
SELECT throws_ok($$ SELECT public.begin_audit_verification_request('15200000-0000-4000-8000-000000000301',repeat('b',64)) $$,'P0001','audit_verification_request_conflict','changed pinned context rejected');
RESET ROLE;
SELECT is((SELECT count(*) FROM private.audit_verification_requests WHERE request_id='15200000-0000-4000-8000-000000000301'),1::bigint,'one immutable mapping was created');
SELECT is((SELECT count(*) FROM private.audit_archive_items WHERE run_id=current_setting('test.request.run')::uuid AND id='15200000-0000-4000-8000-000000000303'),0::bigint,'retry does not mix a later audit event into the snapshot');
SELECT throws_ok($$ UPDATE private.audit_verification_requests SET context_digest=repeat('c',64) WHERE request_id='15200000-0000-4000-8000-000000000301' $$,'P0001',NULL,'mapping cannot be rewritten');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$ SELECT public.begin_audit_verification_request('15200000-0000-4000-8000-000000000302',repeat('a',64)) $$,'42501',NULL,'authenticated cannot execute');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
